#include <Arduino.h>
#include <BleGamepad.h>
#include <NimBLEDevice.h>
#include <math.h>
#include <vector>

// ==========================================================
//                  BLUETOOTH SOZLAMALARI
// ==========================================================

BleGamepad bleGamepad(
  "Virus",
  "Buqa",
  100);

const uint32_t BLE_PASSKEY = 482731;

const bool MAC_FILTER_ENABLED = true;
bleGamepadCarKey Gamepad
const char* ALLOWED_MACS[] = {
  "3C:19:CB:F6:2B:84",
  "A0:FB:C5:E6:D0:17"
  // Ikkinchi telefon kerak bo'lsa:
  // ,"11:22:33:44:55:66"
};

const int ALLOWED_MAC_COUNT =
  sizeof(ALLOWED_MACS) / sizeof(ALLOWED_MACS[0]);


// ----------------------------------------------------------
// XAVFSIZLIK TALABLARI
// ----------------------------------------------------------

// Bluetooth aloqa shifrlangan bo'lishi kerak
const bool REQUIRE_ENCRYPTION = true;

// PIN orqali autentifikatsiya qilingan bo'lishi kerak
const bool REQUIRE_AUTHENTICATION = true;


// ----------------------------------------------------------
// BONDINGNI TOZALASH
// ----------------------------------------------------------

const bool CLEAR_BONDS_ON_BOOT = false;


// ==========================================================
//                    RSSI SOZLAMALARI
// ==========================================================

const int RSSI_AT_1_METER = -59;

const float PATH_LOSS = 2.2;


// ----------------------------------------------------------
// OCHISH / YOPISH CHEGARALARI
// ----------------------------------------------------------

const float UNLOCK_RSSI = -70.0;
const float LOCK_RSSI = -82.0;


// 3 ta ketma-ket yaqin signal
const int UNLOCK_CONFIRM_COUNT = 3;

// 6 ta ketma-ket uzoq signal
const int LOCK_CONFIRM_COUNT = 6;


// Aloqa uzilgandan keyin 10 soniya kutish
const unsigned long DISCONNECT_LOCK_DELAY = 10000;


// RSSI o'lchash oralig'i
const unsigned long RSSI_INTERVAL = 500;


// Autentifikatsiyani tekshirish oralig'i
const unsigned long AUTH_CHECK_INTERVAL = 500;


// ==========================================================
//                       RSSI FILTR
// ==========================================================

const int RSSI_BUFFER_SIZE = 8;

int rssiBuffer[RSSI_BUFFER_SIZE];

int rssiIndex = 0;
int rssiCount = 0;


// ==========================================================
//                    AVTOMOBIL HOLATI
// ==========================================================

enum CarState {
  CAR_LOCKED,
  CAR_UNLOCKED
};

CarState carState = CAR_LOCKED;


// ==========================================================
//                      BLUETOOTH HOLATI
// ==========================================================

bool previousConnected = false;

// Qurilma MAC + xavfsizlik tekshiruvidan o'tdimi?
bool authorizedDevice = false;

// Noto'g'ri MAC sabab uzishga buyruq berildimi?
bool deviceRejected = false;


// ==========================================================
//                         TIMERLAR
// ==========================================================

unsigned long lastRssiTime = 0;
unsigned long lastAuthCheck = 0;
unsigned long disconnectedAt = 0;


// ==========================================================
//                     QULF PINLARI
// ==========================================================

bool a_holat = 1;
bool holat = 0;

const int kutish_r = 100;

#define holat_p 4


// ==========================================================
//                 RSSI TASDIQLASH COUNTER
// ==========================================================

int nearCounter = 0;
int farCounter = 0;


// ==========================================================
//                 FUNKSIYA PROTOTIPLARI
// ==========================================================

void boshqarish(bool eshik, bool _holat);
void ochish();
void yopish();


// ==========================================================
//                 MAC STRINGGA O'TKAZISH
// ==========================================================

String macToString(NimBLEAddress address) {

  String mac =
    String(address.toString().c_str());

  mac.toUpperCase();

  return mac;
}


// ==========================================================
//                    MAC TEKSHIRISH
// ==========================================================

bool isMacAllowed(String mac) {

  mac.toUpperCase();

  for (int i = 0; i < ALLOWED_MAC_COUNT; i++) {

    String allowed =
      String(ALLOWED_MACS[i]);

    allowed.toUpperCase();

    if (mac == allowed) {
      return true;
    }
  }

  return false;
}


// ==========================================================
//             ULANGAN QURILMANI TEKSHIRISH
// ==========================================================

bool checkAuthorization() {

  NimBLEServer* server =
    NimBLEDevice::getServer();


  if (server == nullptr) {
    return false;
  }


  if (server->getConnectedCount() == 0) {
    return false;
  }


  std::vector<uint16_t> peers =
    server->getPeerDevices();


  if (peers.empty()) {
    return false;
  }


  uint16_t handle = peers[0];


  NimBLEConnInfo info =
    server->getPeerInfoByHandle(handle);


  // --------------------------------------------------------
  // MAC MANZILLAR
  // --------------------------------------------------------

  String otaMac =
    macToString(
      info.getAddress());


  String idMac =
    macToString(
      info.getIdAddress());


  Serial.println();
  Serial.println("========== BLUETOOTH XAVFSIZLIK ==========");

  Serial.print("OTA MAC: ");
  Serial.println(otaMac);

  Serial.print("ID MAC:  ");
  Serial.println(idMac);


  // --------------------------------------------------------
  // SECURITY HOLATI
  // --------------------------------------------------------

  Serial.print("Bonded: ");

  Serial.println(
    info.isBonded()
      ? "HA"
      : "YO'Q");


  Serial.print("Encrypted: ");

  Serial.println(
    info.isEncrypted()
      ? "HA"
      : "YO'Q");


  Serial.print("Authenticated: ");

  Serial.println(
    info.isAuthenticated()
      ? "HA"
      : "YO'Q");


  Serial.print("Security key: ");

  Serial.print(
    info.getSecKeySize());

  Serial.println(" byte");


  // --------------------------------------------------------
  // AVVAL SECURITY TAYYOR BO'LISHINI KUTAMIZ
  // --------------------------------------------------------

  if (
    REQUIRE_ENCRYPTION && !info.isEncrypted()) {

    Serial.println(
      ">>> Shifrlangan aloqa kutilmoqda...");

    Serial.println(
      "=========================================");

    return false;
  }


  if (
    REQUIRE_AUTHENTICATION && !info.isAuthenticated()) {

    Serial.println(
      ">>> PIN autentifikatsiyasi kutilmoqda...");

    Serial.println(
      "=========================================");

    return false;
  }


  // --------------------------------------------------------
  // MAC FILTR O'CHIRILGAN BO'LSA
  // --------------------------------------------------------

  if (!MAC_FILTER_ENABLED) {

    Serial.println(
      ">>> MAC FILTER O'CHIRILGAN");

    Serial.println(
      ">>> QURILMAGA RUXSAT BERILDI");

    Serial.println(
      "=========================================");

    return true;
  }


  // --------------------------------------------------------
  // MAC TEKSHIRISH
  // --------------------------------------------------------

  bool macAllowed =
    isMacAllowed(idMac) || isMacAllowed(otaMac);


  if (macAllowed) {

    Serial.println();
    Serial.println(
      ">>> MAC TASDIQLANDI");

    Serial.println(
      ">>> AVTOMOBIL KALITI TASDIQLANDI");

    Serial.println(
      "=========================================");

    return true;
  }


  // --------------------------------------------------------
  // RUXSATSIZ QURILMA
  // --------------------------------------------------------

  Serial.println();
  Serial.println(
    "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!");

  Serial.println(
    "!!! RUXSAT BERILMAGAN QURILMA !!!");

  Serial.println(
    "!!! BLUETOOTH UZILMOQDA !!!");

  Serial.println(
    "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!");


  deviceRejected = true;

  server->disconnect(handle);

  return false;
}


// ==========================================================
//                       YOPISH
// ==========================================================

void yopish() {

  if (!holat) {

    boshqarish(
      true,
      true);

  } else {

    Serial.println(
      "Qulf allaqachon yopiq!");
  }
}


// ==========================================================
//                       OCHISH
// ==========================================================

void ochish() {

  if (holat) {

    boshqarish(
      true,
      false);

  } else {

    Serial.println(
      "Qulf allaqachon ochiq!");
  }
}


// ==========================================================
//                    AVTOMOBILNI OCHISH
// ==========================================================

void unlockCar() {

  if (carState == CAR_UNLOCKED) {
    return;
  }


  Serial.println();
  Serial.println(
    ">>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>");

  Serial.println(
    ">>> OCHISH BUYRUG'I <<<");

  Serial.println(
    "<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<");


  ochish();


  carState =
    CAR_UNLOCKED;


  nearCounter = 0;
  farCounter = 0;
}


// ==========================================================
//                    AVTOMOBILNI YOPISH
// ==========================================================

void lockCar() {

  if (carState == CAR_LOCKED) {
    return;
  }


  Serial.println();
  Serial.println(
    ">>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>");

  Serial.println(
    ">>> YOPISH BUYRUG'I <<<");

  Serial.println(
    "<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<");


  yopish();


  carState =
    CAR_LOCKED;


  nearCounter = 0;
  farCounter = 0;
}


// ==========================================================
//                   RSSI FILTRNI TOZALASH
// ==========================================================

void clearRssiFilter() {

  rssiIndex = 0;
  rssiCount = 0;

  for (
    int i = 0;
    i < RSSI_BUFFER_SIZE;
    i++) {

    rssiBuffer[i] = 0;
  }
}


// ==========================================================
//                    RSSI QO'SHISH
// ==========================================================

void addRssi(int rssi) {

  if (rssi == 0) {
    return;
  }


  rssiBuffer[rssiIndex] =
    rssi;


  rssiIndex++;


  if (
    rssiIndex >= RSSI_BUFFER_SIZE) {

    rssiIndex = 0;
  }


  if (
    rssiCount < RSSI_BUFFER_SIZE) {

    rssiCount++;
  }
}


// ==========================================================
//                    O'RTACHA RSSI
// ==========================================================

float getAverageRssi() {

  if (rssiCount == 0) {
    return 0;
  }


  long total = 0;


  for (
    int i = 0;
    i < rssiCount;
    i++) {

    total +=
      rssiBuffer[i];
  }


  return (float)total / (float)rssiCount;
}


// ==========================================================
//                  RSSI -> MASOFA
// ==========================================================

float rssiToDistance(float rssi) {

  if (rssi == 0) {
    return -1;
  }


  float exponent =

    ((float)RSSI_AT_1_METER - rssi)

    /

    (10.0 * PATH_LOSS);


  return pow(
    10.0,
    exponent);
}


// ==========================================================
//             ULANGAN QURILMANING RSSI SI
// ==========================================================

int getConnectedRssi() {

  NimBLEServer* server =
    NimBLEDevice::getServer();


  if (server == nullptr) {
    return 0;
  }


  if (
    server->getConnectedCount()
    == 0) {

    return 0;
  }


  std::vector<uint16_t> peers =
    server->getPeerDevices();


  if (peers.empty()) {
    return 0;
  }


  uint16_t connectionHandle =
    peers[0];


  NimBLEClient* client =
    server->getClient(
      connectionHandle);


  if (client == nullptr) {
    return 0;
  }


  int rssi =
    client->getRssi();


  server->deleteClient();


  return rssi;
}


// ==========================================================
//                OCHISH / YOPISH LOGIKASI
// ==========================================================

void processCarKey(float rssi) {

  // Ruxsat berilmagan qurilma
  // hech qachon bu yerga kira olmaydi.
  if (!authorizedDevice) {
    return;
  }


  // ========================================================
  // QULFLANGAN
  // ========================================================

  if (
    carState == CAR_LOCKED) {

    if (
      rssi >= UNLOCK_RSSI) {

      nearCounter++;


      Serial.print(
        "Yaqinlashish: ");

      Serial.print(
        nearCounter);

      Serial.print("/");

      Serial.println(
        UNLOCK_CONFIRM_COUNT);

    } else {

      nearCounter = 0;
    }


    if (
      nearCounter >= UNLOCK_CONFIRM_COUNT) {

      unlockCar();
    }
  }


  // ========================================================
  // OCHIQ
  // ========================================================

  else if (
    carState == CAR_UNLOCKED) {

    if (
      rssi <= LOCK_RSSI) {

      farCounter++;


      Serial.print(
        "Uzoqlashish: ");

      Serial.print(
        farCounter);

      Serial.print("/");

      Serial.println(
        LOCK_CONFIRM_COUNT);

    } else {

      farCounter = 0;
    }


    if (
      farCounter >= LOCK_CONFIRM_COUNT) {

      lockCar();
    }
  }
}


// ==========================================================
//                    SIGNAL HOLATI
// ==========================================================

void printSignalState(float rssi) {

  Serial.print(
    "Signal: ");


  if (
    rssi >= UNLOCK_RSSI) {

    Serial.println(
      "OCHISH HUDUDI");

  }

  else if (
    rssi <= LOCK_RSSI) {

    Serial.println(
      "YOPISH HUDUDI");

  }

  else {

    Serial.println(
      "ORALIQ HUDUD");
  }
}


// ==========================================================
//                  QULF BOSHQARUVI
// ==========================================================

void boshqarish(bool eshik,bool _holat) {

  if (_holat) {digitalWrite(17, HIGH);
  } else {digitalWrite(18,HIGH);}
  if (eshik) {digitalWrite(12,HIGH);}
  delay(kutish_r);
  if (_holat) {Serial.println("Eshik yopildi");
  } else {Serial.println("Eshik ochildi");
  }
  digitalWrite(18, LOW);
  digitalWrite(17,LOW);
  digitalWrite(12,LOW);
}


// ==========================================================
//                         SETUP
// ==========================================================

void setup() {

  Serial.begin(115200);
  pinMode(12, OUTPUT);
  pinMode(17, OUTPUT);
  pinMode(18, OUTPUT);
  pinMode(holat_p, INPUT_PULLUP);
  digitalWrite(12, LOW);
  digitalWrite(17, LOW);
  digitalWrite(18, LOW);
  delay(1500);

  holat = digitalRead(holat_p);
  a_holat = holat;

  if (holat) {carState = CAR_LOCKED;
  } else {carState = CAR_UNLOCKED;}

  // --------------------------------------------------------
  // START
  // --------------------------------------------------------

  Serial.println();
  Serial.println("========================================");

  Serial.println(" ESP32 CAR KEY");

  Serial.println("========================================");

  Serial.println();


  Serial.print("Boshlang'ich qulf holati: ");

  Serial.println(
    carState == CAR_LOCKED
      ? "QULFLANGAN"
      : "OCHIQ");


  clearRssiFilter();


  // --------------------------------------------------------
  // GAMEPADNI ISHGA TUSHIRISH
  // --------------------------------------------------------

  bleGamepad.begin();


  delay(100);


  // --------------------------------------------------------
  // BLUETOOTH SECURITY
  // --------------------------------------------------------

  /*
     bonding = true
     MITM    = true
     Secure Connections = true
  */

  // NimBLEDevice::setSecurityAuth(true, false, false);
  // NimBLEDevice::setSecurityIOCap(BLE_HS_IO_DISPLAY_ONLY);
  // NimBLEDevice::setSecurityPasskey(BLE_PASSKEY);

  if (CLEAR_BONDS_ON_BOOT) {

    Serial.println();
    Serial.println("!!! BARCHA OLDINGI BONDING O'CHIRILMOQDA !!!");
    NimBLEDevice::deleteAllBonds();
    delay(500);
  }

  // --------------------------------------------------------
  // DISCONNECT BO'LGANDA REKLAMANI QAYTA BOSHLASH
  // --------------------------------------------------------

  NimBLEServer* server =
    NimBLEDevice::getServer();


  if (server != nullptr) {

    server->advertiseOnDisconnect(
      true);
  }


  // --------------------------------------------------------
  // INFO
  // --------------------------------------------------------

  Serial.println();
  Serial.println(
    "CarKey Gamepad ishga tushdi.");


  Serial.print(
    "Bluetooth PIN: ");

  Serial.printf(
    "%06lu\n",
    (unsigned long)BLE_PASSKEY);


  Serial.print(
    "OCHISH RSSI: ");

  Serial.println(
    UNLOCK_RSSI);


  Serial.print(
    "YOPISH RSSI: ");

  Serial.println(
    LOCK_RSSI);


  Serial.print(
    "MAC filter: ");

  Serial.println(
    MAC_FILTER_ENABLED
      ? "YOQILGAN"
      : "O'CHIRILGAN");


  Serial.println();
}


// ==========================================================
//                          LOOP
// ==========================================================

void loop() {

  // ========================================================
  // REAL QULF HOLATI
  // ========================================================

  holat =digitalRead(holat_p);

  if (
    a_holat != holat) {
    a_holat = holat;

    Serial.print(
      "Qulf holati o'zgardi: ");

    Serial.println(
      holat
        ? "YOPIQ"
        : "OCHIQ");
    // Sizning oldingi logikangiz saqlandi.
    boshqarish(
      false,
      holat);

    // Dasturdagi holatni ham real holat bilan tenglashtiramiz.
    if (holat) {
      carState =
        CAR_LOCKED;

    } else {

      carState =
        CAR_UNLOCKED;
    }
  }

  // ========================================================
  // BLUETOOTH HOLATI
  // ========================================================

  bool connected =
    bleGamepad.isConnected();

  // ========================================================
  // CONNECTION O'ZGARDI
  // ========================================================

  if (
    connected != previousConnected) {

    previousConnected =
      connected;


    // ------------------------------------------------------
    // ULANDI
    // ------------------------------------------------------

    if (connected) {

      Serial.println();
      Serial.println(
        "########################################");

      Serial.println(
        ">>> BLUETOOTH QURILMA ULANDI");

      Serial.println(
        ">>> XAVFSIZLIK TEKSHIRILMOQDA...");

      Serial.println(
        "########################################");
      authorizedDevice =
        false;
      deviceRejected =
        false;
      clearRssiFilter();
      nearCounter = 0;
      farCounter = 0;
      disconnectedAt = 0;
      lastAuthCheck = 0;
    }

    // ------------------------------------------------------
    // UZILDI
    // ------------------------------------------------------

    else {
      Serial.println();
      Serial.println(
        "########################################");
      Serial.println(
        ">>> BLUETOOTH QURILMA UZILDI");
      Serial.println(
        "########################################");


      /*
         Faqat haqiqiy tasdiqlangan kalit
         uzilgan bo'lsa, 10 soniyalik
         yopish timerini boshlaymiz.
      */

      if (
        authorizedDevice) {

        disconnectedAt =
          millis();
      }
      authorizedDevice =
        false;
      deviceRejected =
        false;
      clearRssiFilter();
      nearCounter = 0;
      farCounter = 0;
    }
  }

  // ========================================================
  // ULANGAN, LEKIN HALI TASDIQLANMAGAN
  // ========================================================

  if (
    connected && !authorizedDevice && !deviceRejected) {
    if (
      millis() - lastAuthCheck
      >= AUTH_CHECK_INTERVAL) {
      lastAuthCheck =
        millis();
      authorizedDevice =
        checkAuthorization();

      if (authorizedDevice) {
        Serial.println();
        Serial.println(
          "***************************************");
        Serial.println(
          "*** TELEFON AVTOMOBIL KALITI SIFATIDA ***");
        Serial.println(
          "***          TASDIQLANDI             ***");
        Serial.println(
          "***************************************");
        clearRssiFilter();
        nearCounter = 0;
        farCounter = 0;
      }
    }
  }

  // ========================================================
  // FAQAT RUXSAT BERILGAN TELEFON RSSI SI
  // ========================================================

  if (
    connected && authorizedDevice) {
    if (
      millis() - lastRssiTime
      >= RSSI_INTERVAL) {
      lastRssiTime =
        millis();
      int rawRssi =
        getConnectedRssi();
      if (
        rawRssi != 0) {
        addRssi(
          rawRssi);
        float averageRssi =
          getAverageRssi();
        float distance =
          rssiToDistance(
            averageRssi);
        Serial.println(
          "----------------------------------------");
        Serial.print(
          "Raw RSSI:      ");
        Serial.print(
          rawRssi);
        Serial.println(
          " dBm");
        Serial.print(
          "O'rtacha RSSI: ");
        Serial.print(
          averageRssi,
          1);
        Serial.println(
          " dBm");
        Serial.print(
          "Taxminiy masofa: ");
        Serial.print(
          distance,
          2);
        Serial.println(
          " metr");
        Serial.print(
          "Avtomobil: ");
        if (
          carState == CAR_LOCKED) {
          Serial.println(
            "QULFLANDI");
        } else {

          Serial.println(
            "OCHILDI");
        }
        printSignalState(
          averageRssi);
        if (
          rssiCount >= 4) {
          processCarKey(
            averageRssi);
        }
        Serial.println(
          "----------------------------------------");
      }
    }

    // ========================================================
    // TELEFON UZILGAN
    // ========================================================

    else if (!connected) {
      if (
        carState == CAR_UNLOCKED
        && disconnectedAt != 0
        && millis() - disconnectedAt
             >= DISCONNECT_LOCK_DELAY) {
        Serial.println();
        Serial.println(
          "Telefon 10 soniya davomida qayta ulanmadi.");
        lockCar();
        disconnectedAt = 0;
      }
    }
    delay(20);
  }}
